 o28.platforms.push({id:'base',x:80,y:2496,w:96,h:10,dx:0,rest:0});
 // Alternating branches support recovery; amber pods and hostile projectiles
 // supply Bash launch points. Landing on a branch does not require perfect aim.
 for(let i=1;i<=35;i++){
  const y=2496-i*64,side=i%2,rest=i===10||i===20||i===30;
  let x=side?144:40,w=72;
  if(rest){x=i===20?144:40;w=72;}
  const moving=!rest&&[8,18,27].includes(i);
  o28.platforms.push({id:'branch-'+i,x,y,w,h:9,baseX:x,dx:0,moving,rest:rest?i/10:null,phase:i*.79});
  // Gaps between the two ledges remain visible through all foreground effects.
  const lx=rest?128:[122,177,91,137,73,171,119][i%7];
  o28.lamps.push({id:100+i,x:lx,y:y-27,seed:i,pendulum:false});
  if([5,12,16,23,29,33].includes(i))o28.shooters.push({id:i,x:side?220:36,y:y-28,side:side?-1:1,age:i*13,hp:3,pulse:0});
  if([7,14,22,28].includes(i))o28.hazards.push({x:side?32:210,y:y-52,w:14,h:34,phase:i});
 }
 // One additional pod at each turning gap makes intended target order legible.
 o28.lamps.unshift({id:100,x:144,y:2442,seed:0});
 o28.lamps.push({id:136,x:146,y:224,seed:36},{id:137,x:100,y:142,seed:37},{id:138,x:155,y:67,seed:38});
 o28.platforms.push({id:'top-1',x:40,y:224,w:68,h:9,dx:0},{id:'top-2',x:150,y:144,w:58,h:9,dx:0},{id:'exit',x:72,y:48,w:112,h:10,dx:0});
